void DrawMemoryChart(Graphics& g,float x,float y,float width,float height){RoundRect(g,R(x,y,width,height),RGB(12,33,42),12);Text(g,L"内存波动",x+13,y+7,10,C_MUTED,FontStyleBold,90,18);int low=100,high=0;for(int value:g_memoryHistory){low=std::min(low,value);high=std::max(high,value);}low=std::max(0,low-2);high=std::min(100,high+2);if(high-low<8){int middle=(high+low)/2;low=std::max(0,middle-4);high=std::min(100,low+8);low=std::max(0,high-8);}std::wostringstream range;range<<low<<L"–"<<high<<L"% · 近60秒";Text(g,range.str(),x+width-148,y+7,9,C_MUTED,FontStyleRegular,135,18,StringAlignmentFar);float px=x+14,py=y+27,pw=width-28,ph=height-36;for(int i=1;i<=2;i++)Line(g,px,py+ph*i/3.0f,px+pw,py+ph*i/3.0f,RGB(32,62,71));std::array<PointF,60> points{};for(size_t i=0;i<points.size();i++){int value=g_memoryHistory[(g_memoryHistoryNext+i)%g_memoryHistory.size()];float t=(float)(value-low)/(float)std::max(1,high-low);points[i]=PointF(px+pw*i/(points.size()-1),py+ph*(1.0f-t));}GraphicsPath fill;fill.AddLine(PointF(px,py+ph),points.front());fill.AddLines(points.data(),(INT)points.size());fill.AddLine(points.back(),PointF(px+pw,py+ph));fill.CloseFigure();SolidBrush wash(Color(42,103,231,233));g.FillPath(&wash,&fill);Pen line(GColor(C_CYAN),2);line.SetStartCap(LineCapRound);line.SetEndCap(LineCapRound);g.DrawLines(&line,points.data(),(INT)points.size());Dot(g,points.back().X-3,points.back().Y-3,6,C_CYAN);}
